// Nest's isParameterDecoratorOptions: `in` guarded by a typeof test.
export function isOptions(value) {
  return !!value && typeof value === 'object' && ('schema' in value || 'pipes' in value);
}
export function hasLength(value) { return 'length' in value; }
export function Param(property) { return isOptions(property) ? 'options' : 'name'; }
